import React, { useState, useContext, useEffect } from 'react';
import './booking.css';
import { Form, FormGroup, ListGroup, ListGroupItem, Button } from 'reactstrap';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../../context/AuthContext';
import { BASE_URL } from '../../utils/config';

const Booking = ({ tour, avgRating }) => {
  const { price, reviews, title, _id } = tour;
  const navigate = useNavigate();
  const { user } = useContext(AuthContext);

  const [booking, setBooking] = useState({
    tourId: _id || '',
    tourName: title || '',
    userId: user?._id || '',
    userEmail: user?.email || '',
    fullName: user?.username || '',
    phone: '',
    guestSize: 1,
    bookingAt: '',
    specialRequest: '',
  });

  useEffect(() => {
    setBooking(prev => ({
      ...prev,
      tourId: _id || prev.tourId,
      tourName: title || prev.tourName,
      userId: user?._id || prev.userId,
      userEmail: user?.email || prev.userEmail,
      fullName: user?.username || prev.fullName,
    }));
  }, [user, _id, title]);

  const handleChange = e => {
    const { id, value } = e.target;
    setBooking(prev => ({
      ...prev,
      [id]: id === 'guestSize' ? Number(value) : value,
    }));
  };

  const serviceFee = 450000;
  const totalAmount = Number(price || 0) * Number(booking.guestSize || 1) + Number(serviceFee);

  const handleClick = async e => {
    e.preventDefault();

    if (!user) {
      return alert('Bạn cần đăng nhập để đặt tour');
    }
    if (!booking.bookingAt) {
      return alert('Vui lòng chọn ngày khởi hành');
    }
    if (booking.guestSize <= 0) {
      return alert('Số lượng khách phải lớn hơn 0');
    }

    const payload = {
      tourId: booking.tourId,
      fullName: booking.fullName,
      phone: booking.phone,
      guestSize: booking.guestSize,
      bookingAt: booking.bookingAt,
      specialRequest: booking.specialRequest,
    };

    const token = localStorage.getItem('token');

    try {
      const res = await fetch(`${BASE_URL}/booking`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      const result = await res.json();
      if (!res.ok) {
        return alert(result.message || 'Không thể tạo booking');
      }

      const paymentRes = await fetch(`${BASE_URL}/booking/${result.data._id}/pay`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ method: 'online' }),
      });
      const paymentResult = await paymentRes.json();
      if (!paymentRes.ok) {
        return alert(paymentResult.message || 'Thanh toán thất bại');
      }

      navigate('/thank-you');
    } catch (err) {
      alert(err.message || 'Lỗi kết nối tới server');
    }
  };

  return (
    <div className="booking">
      <div className="booking_top d-flex align-items-center justify-content-between">
        <h3>{Number(price || 0).toLocaleString('vi-VN')}đ <span>/1 người</span></h3>
        <span className='tour_rating d-flex align-items-center'>
          <i className="ri-star-line"></i> {avgRating === 0 ? null : avgRating} ({reviews?.length || 0})
        </span>
      </div>

      <div className="booking_form">
        <h5>Thông tin</h5>
        <Form className="booking_info-form" onSubmit={handleClick}>
          <FormGroup>
            <input
              type="text"
              placeholder='Họ và tên'
              id='fullName'
              required
              value={booking.fullName}
              onChange={handleChange}
            />
          </FormGroup>
          <FormGroup>
            <input
              type="text"
              placeholder='Số điện thoại'
              id='phone'
              required
              value={booking.phone}
              onChange={handleChange}
            />
          </FormGroup>
          <FormGroup className="d-flex align-items-center gap-3">
            <input
              type="date"
              id='bookingAt'
              required
              value={booking.bookingAt}
              onChange={handleChange}
            />
            <input
              type="number"
              placeholder='Số lượng'
              id='guestSize'
              required
              min='1'
              max={tour.maxGroupSize || 1}
              value={booking.guestSize}
              onChange={handleChange}
            />
          </FormGroup>
        </Form>
      </div>

      <div className="booking_bottom">
        <ListGroup>
          <ListGroupItem className="border-0 px-0">
            <h5 className='d-flex align-items-center gap-1'>
              {Number(price || 0).toLocaleString('vi-VN')}đ <i className="ri-close-line"></i> 1 người
            </h5>
            <span>{Number(price || 0).toLocaleString('vi-VN')}đ</span>
          </ListGroupItem>
          <ListGroupItem className="border-0 px-0">
            <h5>Phí dịch vụ</h5>
            <span>{Number(serviceFee).toLocaleString('vi-VN')}đ</span>
          </ListGroupItem>
          <ListGroupItem className="border-0 px-0 total">
            <h5>Tổng cộng</h5>
            <span>{Number(totalAmount).toLocaleString('vi-VN')}đ</span>
          </ListGroupItem>
        </ListGroup>

        <Button className='btn primary_btn w-100 mt-4' onClick={handleClick}>Đặt và Thanh toán</Button>
      </div>
    </div>
  );
};

export default Booking;
